import {FISH_BY_ID,ITEM_BY_ID} from './fishing-data.js';
import {WANDS,WAND_BY_ID} from './magic-data.js';
export const SAVE_KEY='uspeak-fishing-v1';
export function createFishingStore(storage,onSaveError=()=>{}){
 const blank=()=>({coins:0,wands:[WANDS[0].id],wand:WANDS[0].id,inventory:{},discovered:[],owned:[],equipped:{outfit:null,weapon:null},caught:0});let value=blank();
 try{const s=JSON.parse(storage.getItem(SAVE_KEY));if(s&&typeof s==='object'){value.coins=Number.isSafeInteger(s.coins)&&s.coins>=0&&s.coins<=1e9?s.coins:0;for(const [id,n]of Object.entries(s.inventory||{}))if(FISH_BY_ID[id]&&Number.isSafeInteger(n)&&n>0&&n<=100000)value.inventory[id]=n;value.discovered=[...new Set([...(Array.isArray(s.discovered)?s.discovered:[]),...Object.keys(value.inventory)])].filter(id=>FISH_BY_ID[id]);value.owned=[...new Set(Array.isArray(s.owned)?s.owned:[])].filter(id=>ITEM_BY_ID[id]);for(const k of ['outfit','weapon'])if(value.owned.includes(s.equipped?.[k])&&ITEM_BY_ID[s.equipped[k]].kind===k)value.equipped[k]=s.equipped[k];value.wands=[...new Set([WANDS[0].id,...(Array.isArray(s.wands)?s.wands:[])])].filter(id=>Object.hasOwn(WAND_BY_ID,id));value.wand=value.wands.includes(s.wand)?s.wand:WANDS[0].id;value.caught=Number.isSafeInteger(s.caught)&&s.caught>=0?s.caught:Object.values(value.inventory).reduce((a,b)=>a+b,0)}}catch{}
 let warned=false;function commit(next){try{storage.setItem(SAVE_KEY,JSON.stringify(next))}catch{if(!warned){warned=true;onSaveError()}}value=next;return next}const copy=()=>JSON.parse(JSON.stringify(value));
 return {get state(){return copy()},catchFish(id){if(!FISH_BY_ID[id])throw new Error('魚が見つかりません');const n=copy();n.inventory[id]=(n.inventory[id]||0)+1;if(!n.discovered.includes(id))n.discovered.push(id);n.caught++;return commit(n)},sell(id,quantity=1){const n=copy(),count=n.inventory[id]||0;if(!FISH_BY_ID[id]||!Number.isSafeInteger(quantity)||quantity<1||quantity>count)throw new Error('売れる魚の数を確認してください');const amount=FISH_BY_ID[id].price*quantity;n.inventory[id]-=quantity;if(!n.inventory[id])delete n.inventory[id];n.coins+=amount;commit(n);return amount},sellAll(){const n=copy(),amount=Object.entries(n.inventory).reduce((s,[id,num])=>s+FISH_BY_ID[id].price*num,0);if(!amount)throw new Error('売れる魚がありません');n.inventory={};n.coins+=amount;commit(n);return amount},buy(id){const item=ITEM_BY_ID[id];if(!item)throw new Error('商品が見つかりません');const n=copy();if(n.owned.includes(id))throw new Error('すでに持っています');if(n.coins<item.price)throw new Error(`あと ${item.price-n.coins} コイン必要です`);n.coins-=item.price;n.owned.push(id);commit(n)},equip(id){const item=ITEM_BY_ID[id];if(!item||!value.owned.includes(id))throw new Error('購入した装備を選んでください');const n=copy();n.equipped[item.kind]=id;commit(n)},unequip(kind){if(!['outfit','weapon'].includes(kind))return;const n=copy();n.equipped[kind]=null;commit(n)},buyWand(id){const w=WAND_BY_ID[id],n=copy();if(!w||n.wands.includes(id))throw new Error('この杖は購入済み、または見つかりません。');if(n.coins<w.price)throw new Error('あと '+(w.price-n.coins)+' コイン必要です。');n.coins-=w.price;n.wands.push(id);n.wand=id;commit(n)},equipWand(id){if(!value.wands.includes(id))throw new Error('持っている杖を選んでください。');const n=copy();n.wand=id;commit(n)},inventoryValue(){return Object.entries(value.inventory).reduce((s,[id,n])=>s+FISH_BY_ID[id].price*n,0)}};
}
